    else
      printf "  ${RED}[✗]${RESET} %-26s ${YELLOW}missing${RESET}\n" "$(basename "$cfg")"
    fi
  done

  echo ""
  echo -e "${BOLD}${CYAN}  ════════════════════════════════════════════════════════════════════${RESET}"
}

