# =============================================================================
fpath+=\${ZSH_CUSTOM:-\${ZSH:-~/.oh-my-zsh}/custom}/plugins/zsh-completions/src

# =============================================================================
# Plugins — syntax-highlighting MUST be last
# =============================================================================
plugins=(
  git
  sudo
  history-substring-search
  colored-man-pages
  colorize
  extract
  command-not-found
